import{_ as t,o as a,c as o,a2 as n}from"./chunks/framework.Nk14N-ai.js";const u=JSON.parse('{"title":"Introduction","description":"","frontmatter":{},"headers":[],"relativePath":"introduction.md","filePath":"introduction.md"}'),r={name:"introduction.md"};function i(s,e,l,c,d,h){return a(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to &quot;Introduction&quot;">​</a></h1><p><em>A sovereign namespace engine secured purely by math and time.</em><em>Created by <a href="https://saifmukhtar.dev" target="_blank" rel="noreferrer">Saif Mukhtar</a></em></p><blockquote><p><strong>Official IETF Internet-Drafts:</strong></p><ul><li><a href="https://www.ietf.org/archive/id/draft-mukhtar-kinetic-network-00.html" target="_blank" rel="noreferrer">draft-mukhtar-kinetic-network-00</a></li><li><a href="https://www.ietf.org/archive/id/draft-mukhtar-kinetic-identity-00.html" target="_blank" rel="noreferrer">draft-mukhtar-kinetic-identity-00</a></li></ul></blockquote><hr><h2 id="what-kinetic-actually-is" tabindex="-1">What Kinetic Actually Is <a class="header-anchor" href="#what-kinetic-actually-is" aria-label="Permalink to &quot;What Kinetic Actually Is&quot;">​</a></h2><p>Kinetic is not a domain registrar. It is not a blockchain. It is not another <code>.eth</code> or <code>.crypto</code>.</p><p><strong>Kinetic is an open-source namespace engine</strong> — a Rust binary suite that any university, company, government, or community can deploy to run their own cryptographically secured naming network. You configure one file (<code>network.json</code>), run <code>kinetic-forge</code>, and walk away with a complete, self-contained network with your own TLD, your own bootstrap nodes, and your own governance keys.</p><p>The canonical public deployment of this engine is the <strong><code>.kin</code> network</strong> — a permissionless global commons where no single entity holds administrative authority. <code>.kin</code> is the proof that the engine works without any operator at all.</p><p><strong>Two ways to use Kinetic:</strong></p><table tabindex="0"><thead><tr><th></th><th>Fork Your Own Network</th><th>Use the <code>.kin</code> Network</th></tr></thead><tbody><tr><td><strong>Who</strong></td><td>Universities, companies, governments, communities</td><td>Developers, open-source builders, privacy advocates</td></tr><tr><td><strong>TLD</strong></td><td>Whatever you configure (<code>.uni</code>, <code>.acme</code>, <code>.internal</code>)</td><td><code>.kin</code></td></tr><tr><td><strong>Control</strong></td><td>You hold the governance keys. You can reset.</td><td>No operator. Math governs it.</td></tr><tr><td><strong>Squatters</strong></td><td>VDF cliff + you can restart the network</td><td>VDF cliff alone</td></tr><tr><td><strong>Entry point</strong></td><td><a href="./forking.html"><code>kinetic-forge</code></a></td><td><a href="./getting_started.html"><code>Getting Started</code></a></td></tr></tbody></table><hr><h2 id="choose-your-path" tabindex="-1">Choose Your Path <a class="header-anchor" href="#choose-your-path" aria-label="Permalink to &quot;Choose Your Path&quot;">​</a></h2><h3 id="🍴-i-want-to-deploy-my-own-network" tabindex="-1">🍴 I want to deploy my own network <a class="header-anchor" href="#🍴-i-want-to-deploy-my-own-network" aria-label="Permalink to &quot;🍴 I want to deploy my own network&quot;">​</a></h3><p>→ Start with <strong><a href="./forking.html">Fork Your Own Network</a></strong></p><p>This covers <code>kinetic-forge</code>, <code>network.json</code>, swappable <code>VdfEngine</code> and <code>StorageEngine</code> backends, bootstrap node setup, and the fork squatter economics that make private networks self-defending.</p><h3 id="🌐-i-want-to-register-a-kin-name" tabindex="-1">🌐 I want to register a <code>.kin</code> name <a class="header-anchor" href="#🌐-i-want-to-register-a-kin-name" aria-label="Permalink to &quot;🌐 I want to register a `.kin` name&quot;">​</a></h3><p>→ Start with <strong><a href="./getting_started.html">Getting Started</a></strong></p><p>This covers installing the daemon, the two-phase commit/reveal registration, configuring your Capability Manifest, and keeping your name alive with the heartbeat system.</p><h3 id="🔐-i-want-to-understand-the-cryptography" tabindex="-1">🔐 I want to understand the cryptography <a class="header-anchor" href="#🔐-i-want-to-understand-the-cryptography" aria-label="Permalink to &quot;🔐 I want to understand the cryptography&quot;">​</a></h3><p>→ Start with <strong><a href="./cryptography.html">The Mathematical Engine</a></strong></p><p>This covers VDFs over Class Groups, the Wesolowski proof protocol, the <code>drand</code> Quicknet beacon, and Ed25519 identity binding. No prior cryptography knowledge assumed.</p><h3 id="📡-i-want-to-run-infrastructure-or-contribute" tabindex="-1">📡 I want to run infrastructure or contribute <a class="header-anchor" href="#📡-i-want-to-run-infrastructure-or-contribute" aria-label="Permalink to &quot;📡 I want to run infrastructure or contribute&quot;">​</a></h3><p>→ Start with <strong><a href="./network_architecture.html">Network Architecture</a></strong></p><p>This covers the Immunological DHT, Redundant Deterministic Storage, Competitive Gossip validation, and the <code>kinetic-node</code> headless infrastructure binary.</p><hr><h2 id="why-this-had-to-be-built" tabindex="-1">Why This Had to Be Built <a class="header-anchor" href="#why-this-had-to-be-built" aria-label="Permalink to &quot;Why This Had to Be Built&quot;">​</a></h2><p>To understand why Kinetic exists, you need to understand what every previous attempt at decentralized naming got wrong. The problem is older and harder than it looks.</p><h3 id="the-mathematical-constraint-zooko-s-triangle" tabindex="-1">The Mathematical Constraint: Zooko&#39;s Triangle <a class="header-anchor" href="#the-mathematical-constraint-zooko-s-triangle" aria-label="Permalink to &quot;The Mathematical Constraint: Zooko&#39;s Triangle&quot;">​</a></h3><p>In 2001, Zooko Wilcox-O&#39;Hearn formalized a trilemma that had been haunting network engineers for decades. Any naming system can have at most two of three properties simultaneously:</p><ol><li><strong>Human-Meaningful</strong> — Names that humans can read, remember, and type (<code>apple</code>, <code>university</code>, <code>example</code>)</li><li><strong>Decentralized</strong> — No central authority controls the namespace</li><li><strong>Secure</strong> — The system resists spoofing and Sybil attacks</li></ol><p>Every approach for the past four decades has failed to achieve all three without introducing a new fatal flaw.</p><hr><h3 id="era-1-icann-and-absolute-centralization-1980s-—-present" tabindex="-1">Era 1: ICANN and Absolute Centralization (1980s — Present) <a class="header-anchor" href="#era-1-icann-and-absolute-centralization-1980s-—-present" aria-label="Permalink to &quot;Era 1: ICANN and Absolute Centralization (1980s — Present)&quot;">​</a></h3><p>The legacy DNS deliberately sacrifices the <strong>Decentralized</strong> leg. It achieves human-meaningful names and security through absolute hierarchical centralization.</p><p>At the top sits ICANN — the Internet Corporation for Assigned Names and Numbers. ICANN has unchecked authority to create TLDs and delegate them to registries. Registries delegate to registrars. Registrars sell to you.</p><p><strong>The consequences:</strong></p><ul><li><strong>Political seizure:</strong> A single phone call can compel ICANN to revoke a domain. No cryptographic due process exists. State actors and corporations exercise this power routinely.</li><li><strong>Monopoly rent extraction:</strong> Verisign holds an artificial monopoly over <code>.com</code>. They charge arbitrary annual fees for a database entry that costs fractions of a cent to maintain. The fee is not a service cost — it is a toll.</li><li><strong>Speculative markets:</strong> Because names are artificially scarce and monetarily valued, an entire predatory industry emerged — domain parking, aftermarket speculation, cybersquatting — that extracts value from builders while producing nothing.</li></ul><p>Legacy DNS is technically functional and deeply unethical. It is digital feudalism: developers lease land from a central sovereign.</p><hr><h3 id="era-2-capital-gated-blockchains-2017-—-present" tabindex="-1">Era 2: Capital-Gated Blockchains (2017 — Present) <a class="header-anchor" href="#era-2-capital-gated-blockchains-2017-—-present" aria-label="Permalink to &quot;Era 2: Capital-Gated Blockchains (2017 — Present)&quot;">​</a></h3><p>Blockchain naming systems (ENS, Handshake, Unstoppable Domains) placed the registry on a decentralized ledger — achieving the <strong>Decentralized</strong> leg. But they immediately confronted the Sybil problem.</p><p>In a permissionless network, generating a request costs effectively nothing. Without a gating mechanism, a single attacker can claim every word in the English dictionary in seconds. So blockchain naming systems instituted a gating function: <strong>Financial Capital</strong>.</p><p><strong>The consequences:</strong></p><ul><li><strong>Digital landlordism, decentralized edition:</strong> Capital-gated registries favor entities with deep financial liquidity. Wealthy speculators hoard short names and extract rent from legitimate builders — exactly the same dynamic as ICANN, just with fewer regulations.</li><li><strong>Developer pricing-out:</strong> A peer-to-peer routing primitive should not require a perpetual subscription fee. Tying infrastructure to cryptocurrency market prices makes development costs unpredictable and inaccessible in developing economies.</li><li><strong>Valuation paradox:</strong> When the underlying token spikes during a bull market, renewal costs spike with it. Names become inaccessible to the people who need them most precisely when the ecosystem is most active.</li></ul><p>Capital-gated registries did not solve digital landlordism. They democratized the ability to be the landlord.</p><hr><h3 id="era-3-proof-of-personhood-2020-—-present" tabindex="-1">Era 3: Proof of Personhood (2020 — Present) <a class="header-anchor" href="#era-3-proof-of-personhood-2020-—-present" aria-label="Permalink to &quot;Era 3: Proof of Personhood (2020 — Present)&quot;">​</a></h3><p>To eliminate capital requirements entirely, some protocols defined the friction mechanism as <strong>physical human uniqueness</strong> — one human, one name.</p><p>Proof of Personhood systems (Worldcoin, BrightID, Proof of Humanity) prevent Sybil attacks by ensuring an attacker cannot generate a million identities without a million physical bodies.</p><p><strong>The consequences:</strong></p><ul><li><strong>Extreme onboarding friction:</strong> Retina scans, synchronous video ceremonies, NFC passport reads, scheduled verification epochs. A developer cannot spin up an ephemeral staging domain at 2 AM if they need to scan their iris first.</li><li><strong>Privacy destruction:</strong> Extracting unique physical identity — even with zero-knowledge proofs — almost always shackles the system to government-issued credentials or biometric hardware. Pseudonymity is sacrificed.</li><li><strong>The multiple-alias reality:</strong> Developers legitimately need multiple names — production, staging, personal, anonymous, testing. A strict 1:1 mapping between a human body and a network handle is an artificial constraint that fundamentally misunderstands how infrastructure is deployed.</li></ul><hr><h3 id="the-kinetic-solution-computational-time-as-friction" tabindex="-1">The Kinetic Solution: Computational Time as Friction <a class="header-anchor" href="#the-kinetic-solution-computational-time-as-friction" aria-label="Permalink to &quot;The Kinetic Solution: Computational Time as Friction&quot;">​</a></h3><p>We are left with an architectural impasse. A truly decentralized namespace cannot survive without friction. But:</p><ul><li>Friction as <strong>central authority</strong> → censorship and seizure</li><li>Friction as <strong>money</strong> → digital landlordism</li><li>Friction as <strong>identity</strong> → onboarding destruction and privacy loss</li></ul><p><strong>Kinetic abandons all three.</strong></p><p>The cost of namespace acquisition is defined strictly as <strong>un-parallelizable sequential computation and time</strong> — returning to the purest form of permissionless security.</p><p>A Verifiable Delay Function (VDF) is a mathematical puzzle that:</p><ul><li>Takes a provably specific amount of time to solve</li><li><strong>Cannot be parallelized</strong> — a billionaire with 10,000 ASICs cannot solve a single VDF faster than a hobbyist on a laptop</li><li>Produces a compact cryptographic proof that anyone can verify in milliseconds</li></ul><p>Kinetic uses VDFs to make squatting computationally ruinous:</p><table tabindex="0"><thead><tr><th>Name Length</th><th>Required Computation</th><th>Time on Modern CPU</th></tr></thead><tbody><tr><td>1 character</td><td>× 1,753,200 baseline</td><td>~100 years</td></tr><tr><td>2 characters</td><td>× 7,200 baseline</td><td>~5 months</td></tr><tr><td>4 characters</td><td>× 720 baseline</td><td>~15 days</td></tr><tr><td>6 characters</td><td>× 24 baseline</td><td>~12 hours</td></tr><tr><td>8+ characters</td><td>× 4 baseline</td><td>~2 hours</td></tr><tr><td>21+ characters</td><td>× 1 baseline</td><td>~30 minutes</td></tr></tbody></table><p>Mass dictionary squatting is not just expensive — it is physically impossible at scale. A single CPU cannot process more than a handful of names per year at the 6-character tier. An attacker with a thousand CPUs still cannot claim a thousand 6-character names in any reasonable timeframe.</p><p>For a single legitimate developer registering one name: <strong>30 minutes of CPU, zero dollars, zero accounts, zero approvals.</strong></p><hr><h2 id="the-engine-philosophy" tabindex="-1">The Engine Philosophy <a class="header-anchor" href="#the-engine-philosophy" aria-label="Permalink to &quot;The Engine Philosophy&quot;">​</a></h2><p>The deepest insight behind Kinetic is that the <code>.kin</code> network — the public canonical deployment — is not the product.</p><p><strong>The engine is the product.</strong></p><p>Every organization that forks Kinetic becomes a stakeholder in the engine&#39;s quality and security. Every university running <code>.uni</code>, every company running <code>.internal</code>, every open-source community running their own TLD — they all benefit from improvements to the shared cryptographic core, and they all contribute to the network effect that makes the engine trustworthy.</p><p><code>.kin</code> is the proof that the engine works without any operator. The forks are the proof that the engine works for everyone.</p><p>Welcome to the Kinetic Protocol.</p>',70)])])}const g=t(r,[["render",i]]);export{u as __pageData,g as default};
